const routeContractVersion = 1 as const
const modelIdMaxLength = 120
const recognizedRouteProviders = new Set<Provider>(['openrouter', 'gemini', 'openai', 'bailian', 'ark', 'deepseek', 'kimi', 'zhipu', 'siliconflow', 'anthropic', 'recraft', 'xai', 'bfl', 'stability', 'ideogram', 'minimax', 'mistral', 'together', 'fireworks', 'fal', 'replicate', 'runware', 'tokenhub', 'xiaomi', 'sensenova', 'stepfun', 'qianfan', 'iflytek', 'longcat', 'antling', 'novita', 'tokendance', 'custom'])

function modelRouteError(message: string, businessCode = 'MODEL_ROUTE_INVALID') {
  const error: any = new Error(message)
  error.statusCode = 400
  error.businessCode = businessCode
  return error
}

function normalizeModelRoute(value: any, role: ModelRole): ModelRoute {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw modelRouteError(`modelRoutes.${role} must be an object`)
  }
  if (value.accessProvider === 'custom') return normalizeUniversalRoute(value)
  const accessProvider = String(value.accessProvider || '').trim() as Provider
  const rawModelId = typeof value.modelId === 'string' ? value.modelId.trim() : ''
  if (!recognizedRouteProviders.has(accessProvider)) {
    throw modelRouteError(`modelRoutes.${role}.accessProvider is invalid`)
  }
  if (!rawModelId || rawModelId.length > modelIdMaxLength) {
    throw modelRouteError(`modelRoutes.${role}.modelId must be between 1 and ${modelIdMaxLength} characters`)
  }
  return { accessProvider, modelId: normalizeModelName(accessProvider, rawModelId) }
}

function hasLegacyModelValue(value: unknown) {
  return typeof value === 'string' && value.trim().length > 0
}

export function resolveModelRouting(body: Record<string, any>): ModelRoutingMetadata {
  const explicit = body.modelRoutes !== undefined && body.modelRoutes !== null
  let modelRoutes: ModelRoutes
  let modelRoutingSource: ModelRoutingSource

  if (explicit) {
    if (!body.modelRoutes || typeof body.modelRoutes !== 'object' || Array.isArray(body.modelRoutes)) {
      throw modelRouteError('modelRoutes must be an object')
    }
    modelRoutes = {
      main: normalizeModelRoute(body.modelRoutes.main, 'main'),
      image: normalizeModelRoute(body.modelRoutes.image, 'image'),
      vision: normalizeModelRoute(body.modelRoutes.vision, 'vision'),
    }
    const legacyProvider = String(body.provider || '').trim()
    const conflicts = [
      Boolean(legacyProvider && legacyProvider !== modelRoutes.main.accessProvider),
      Boolean(hasLegacyModelValue(body.mainModelName)
        && normalizeModelName(modelRoutes.main.accessProvider, String(body.mainModelName).trim()) !== modelRoutes.main.modelId),
      Boolean(hasLegacyModelValue(body.imageModelName)
        && normalizeModelName(modelRoutes.image.accessProvider, String(body.imageModelName).trim()) !== modelRoutes.image.modelId),
      Boolean(hasLegacyModelValue(body.referenceVisionModelName)
        && normalizeModelName(modelRoutes.vision.accessProvider, String(body.referenceVisionModelName).trim()) !== modelRoutes.vision.modelId),
    ]
    if (conflicts.some(Boolean)) {
      throw modelRouteError('Legacy model fields conflict with modelRoutes', 'MODEL_ROUTE_CONFLICT')
    }
    modelRoutingSource = 'explicit'
  } else {
    const provider = String(body.provider || '').trim() as Provider
    if (!recognizedRouteProviders.has(provider)) throw modelRouteError('Invalid provider')
    const mainModelName = typeof body.mainModelName === 'string' ? body.mainModelName.trim() : ''
    const imageModelName = typeof body.imageModelName === 'string' ? body.imageModelName.trim() : ''
    const visionModelName = typeof body.referenceVisionModelName === 'string' && body.referenceVisionModelName.trim()
      ? body.referenceVisionModelName.trim()
      : mainModelName
    modelRoutes = {
      main: normalizeModelRoute({ accessProvider: provider, modelId: mainModelName }, 'main'),
      image: normalizeModelRoute({ accessProvider: provider, modelId: imageModelName }, 'image'),
      vision: normalizeModelRoute({ accessProvider: provider, modelId: visionModelName }, 'vision'),
    }
    modelRoutingSource = 'legacy-derived'
  }

  checkedModelRegions(body.providerRegions, modelRoutes)
  const routingMode: ModelRoutingMode = new Set(Object.values(modelRoutes).map((route) => route.accessProvider === 'custom' ? ['custom',route.custom?.baseUrl,route.custom?.protocol,route.custom?.auth].join('|') : route.accessProvider)).size === 1
    ? 'single'
    : 'mixed'
  if (body.configurationMode === 'simple' && routingMode === 'mixed') {
    throw modelRouteError('Mixed model routes require advanced configuration mode', 'MODEL_ROUTE_MIXED_NOT_ALLOWED')
  }
  const thinkingIdentities = Object.fromEntries(Object.entries(modelRoutes).map(([role, route]) => {
    if (route.accessProvider === 'custom') return [role, universalThinkingIdentity(normalizeUniversalRoute(route))]
    const entry = staticModelRegistry[route.accessProvider as Exclude<Provider, 'openrouter'>]?.models.find(item => item.id === route.modelId)
    const protocol = route.accessProvider === 'custom' ? route.custom?.protocol || 'unconfirmed'
      : entry?.roleProtocols?.[role as ModelRole] || (route.accessProvider === 'openrouter' ? role === 'image' ? 'openrouter-images' : 'openrouter-chat-completions' : entry?.protocol || 'unconfirmed')
    return [role, { provider: route.accessProvider, modelId: route.modelId, protocol, ...(route.accessProvider === 'minimax' ? { region: minimaxRegion(body.providerRegions) } : {}) }]
  }))
  const normalizedThinking = normalizeThinkingConfiguration(body.thinkingConfig, thinkingIdentities)
  validateThinkingTask(normalizedThinking.thinkingSnapshot, body)
  return {
    ...normalizedThinking,
    modelRoutes,
    ...(body.providerRegions === undefined ? {} : { providerRegions: checkedModelRegions(body.providerRegions, modelRoutes) }),
    routingMode,
    modelRoutingVersion: routeContractVersion,
    modelRoutingSource,
    provider: modelRoutes.main.accessProvider,
    mainModelName: modelRoutes.main.modelId,
    imageModelName: modelRoutes.image.modelId,
    referenceVisionModelName: modelRoutes.vision.modelId,
  }
}

function uniqueRouteRoles(roles: ModelRole[]) {
  const requested = new Set(roles)
  return (['main', 'image', 'vision'] as ModelRole[]).filter((role) => requested.has(role))
}

export function requiredCreateRouteRoles(body: Record<string, any>, maxCriticRounds: number): ModelRole[] {
  const roles: ModelRole[] = []
  const outputFormat = normalizeOutputFormat(body.outputFormat || body.output_format)
  const taskName = normalizeTaskName(body.taskName)
  const pipelineMode = body.pipelineMode || 'planner_critic'
  if ((outputFormat === 'svg' && !nativeRecraftVectorRoute(body)) || taskName === 'plot' || pipelineMode !== 'vanilla' || body.retrievalSetting === 'auto') roles.push('main')
  if ((outputFormat === 'png' || nativeRecraftVectorRoute(body)) && taskName !== 'plot') roles.push('image')
  if (taskName === 'plot' && (['1.5K', '2K', '3K', '4K'].includes(body.imageSize)) && body.imageRefineMode === 'direct-edit') roles.push('image')
  if ((body.referenceImages || []).length) roles.push(body.referenceImageModeUsed === 'main_model' ? 'main' : 'vision')
  if (Number(maxCriticRounds || 0) > 0 && (taskName === 'plot' || (outputFormat === 'png' && pipelineMode !== 'vanilla'))) roles.push('vision')
  return uniqueRouteRoles(roles)
}

export function requiredRefineRouteRoles(body: Record<string, any>): ModelRole[] {
  return body.refineMode === 'direct-edit' ? ['image'] : ['vision', 'image']
}

// Resolve credentials for roles the workflow can actually execute. A saved,
// unused TokenDance route must not require a TokenDance connection.
export async function requiresTokenDanceCredential(body: Record<string, any>) {
  if (body.action === 'optimizeInputs') return body.mainRoute?.accessProvider === 'tokendance'
  const routing = resolveModelRouting(body as any)
  const routes = routing.modelRoutes
  const image = routes.image
  let refineMode = 'none'
  if (body.action === 'refineImage' || normalizeTaskName(body.taskName) === 'plot') {
    const registry = await registryForModelRoute(image)
    refineMode = registryImageRefineCapability(image.accessProvider, registry, image.modelId).mode
  }
  const normalized = { ...body, ...routing, refineMode, imageRefineMode: refineMode,
    referenceImageModeUsed: body.referenceImageModeUsed || body.referenceImageMode }
  const roles = body.action === 'refineImage' ? requiredRefineRouteRoles(normalized)
    : requiredCreateRouteRoles(normalized, Number(body.maxCriticRounds ?? 1))
  return roles.some(role => routes[role].accessProvider === 'tokendance')
}

export function selectRequiredRouteSecrets(
  routes: ModelRoutes,
  apiKeys: ApiKeys,
  roles: ModelRole[],
): RouteSecrets {
  const selected: RouteSecrets = {}
  for (const role of roles) {
    const provider = routes[role].accessProvider
    if (provider === 'custom') {
      const route = normalizeUniversalRoute(routes[role])
      const apiKey = universalCredential(route, apiKeys.custom || '')
      const scoped = selected.custom ? JSON.parse(selected.custom) : {}
      scoped[route.custom.connectionId] = {baseUrl: route.custom.baseUrl, protocol: route.custom.protocol, auth: route.custom.auth, apiKey}
      selected.custom = JSON.stringify(scoped)
    } else {
      const secret = selectApiKey(provider, apiKeys)
      if (secret) selected[provider] = secret
    }
  }
  return selected
}

export function createJobAdmissionController(
  config: JobAdmissionConfig,
  dependencies: {
    execute(task: AdmittedJobTask): Promise<void>
    markFailed(jobId: string, error: string, referenceValidation?: boolean, failure?: any): Promise<void>
    logError(message: string): void
  },
) {
  type Entry = {
    id: number
    principal: JobPrincipal
    slot: 'active' | 'queued'
    committed: boolean
    task?: AdmittedJobTask
  }

  let accepting = true
  let nextId = 1
  const entries = new Map<number, Entry>()
  const pendingOrder: Entry[] = []
  const tracked = new Set<Promise<void>>()
  const ownerCounts = new Map<string, number>()
  const ipCounts = new Map<string, number>()
  const drainWaiters = new Set<() => void>()
  const frozenOwners = new Set<string>()
  const ownerDrainWaiters = new Set<{ ownerKeys: Set<string>; resolve: () => void }>()

  const countFor = (counts: Map<string, number>, key: string) => key ? (counts.get(key) || 0) : 0
  const increment = (counts: Map<string, number>, key: string) => {
    if (key) counts.set(key, countFor(counts, key) + 1)
  }
  const decrement = (counts: Map<string, number>, key: string) => {
    if (!key) return
    const next = countFor(counts, key) - 1
    if (next > 0) counts.set(key, next)
    else counts.delete(key)
  }
  const activeSlots = () => [...entries.values()].filter((entry) => entry.slot === 'active').length
  const notifyDrained = () => {
    for (const waiter of [...ownerDrainWaiters]) {
      const ownerBusy = [...entries.values()].some((entry) => waiter.ownerKeys.has(entry.principal.ownerKey))
      if (!ownerBusy) {
        ownerDrainWaiters.delete(waiter)
        waiter.resolve()
      }
    }
    if (entries.size || tracked.size) return
    for (const resolve of drainWaiters) resolve()
    drainWaiters.clear()
  }

  const release = (entry: Entry) => {
    if (!entries.delete(entry.id)) return
    const pendingIndex = pendingOrder.indexOf(entry)
    if (pendingIndex >= 0) pendingOrder.splice(pendingIndex, 1)
    decrement(ownerCounts, entry.principal.ownerKey)
    decrement(ipCounts, entry.principal.ipKey)
    pump()
    notifyDrained()
  }

  const launch = (entry: Entry) => {
    if (!entry.task) return
    const task = entry.task
    const promise = (async () => {
      try {
        await dependencies.execute(task)
      } catch (error: any) {
        const safeTaskError = redactSecretText(
          error?.message || String(error),
          Object.values(task.routeSecrets || {}).filter(Boolean) as string[],
        )
        try {
          await dependencies.markFailed(task.jobId, safeTaskError, error instanceof ReferenceUploadValidationError, { ...error, name: error?.name, message: safeTaskError, status: error?.status, failureStage: error?.failureStage })
        } catch (persistenceError: any) {
          try {
            dependencies.logError(
              `Failed to persist terminal state for ${task.jobId}: ${persistenceError?.message || String(persistenceError)}`,
            )
          } catch {
            // Logging must never re-reject a tracked job.
          }
        }
      } finally {
        release(entry)
      }
    })()
    tracked.add(promise)
    void promise.finally(() => {
      tracked.delete(promise)
      notifyDrained()
    })
  }

  function pump() {
    while (activeSlots() < config.maxActive && pendingOrder.length) {
      const entry = pendingOrder.shift()!
      if (frozenOwners.has(entry.principal.ownerKey)) {
        release(entry)
        continue
      }
      entry.slot = 'active'
      if (!entry.committed) break
      launch(entry)
    }
  }

  return {
    reserve(principal: JobPrincipal) {
      if (!accepting) {
        return { ok: false as const, code: 503, error: 'Job admission is draining. Please retry after restart.' }
      }
      if (frozenOwners.has(principal.ownerKey)) {
        return { ok: false as const, code: 409, error: 'Account deletion is in progress. New jobs and uploads are disabled.' }
      }
      if (countFor(ownerCounts, principal.ownerKey) >= config.maxPerOwner) {
        return { ok: false as const, code: 429, error: 'Job owner limit exceeded. Please wait for the current job to finish.' }
      }
      if (countFor(ipCounts, principal.ipKey) >= config.maxPerIp) {
        return { ok: false as const, code: 429, error: 'Job IP limit exceeded. Please wait for the current job to finish.' }
      }

      const slot = activeSlots() < config.maxActive
        ? 'active' as const
        : pendingOrder.length < config.maxPending
          ? 'queued' as const
          : null
      if (!slot) return { ok: false as const, code: 429, error: 'Job queue is full. Please try again later.' }

      const entry: Entry = { id: nextId++, principal, slot, committed: false }
      entries.set(entry.id, entry)
      if (slot === 'queued') pendingOrder.push(entry)
      increment(ownerCounts, principal.ownerKey)
      increment(ipCounts, principal.ipKey)
      return { ok: true as const, id: entry.id }
    },
    commit(reservation: { ok: true; id: number }, task: AdmittedJobTask) {
      const entry = entries.get(reservation.id)
      if (!entry || entry.committed) return
      entry.committed = true
      entry.task = task
      if (entry.slot === 'active') launch(entry)
      else pump()
    },
    cancel(reservation: { ok: true; id: number }) {
      const entry = entries.get(reservation.id)
      if (entry) release(entry)
    },
    stop() {
      accepting = false
    },
    freezeOwners(ownerKeys: string[]) {
      for (const ownerKey of ownerKeys) {
        if (ownerKey) frozenOwners.add(ownerKey)
      }
      const keys = new Set(ownerKeys.filter(Boolean))
      for (const entry of [...entries.values()]) {
        if (keys.has(entry.principal.ownerKey) && entry.slot === 'queued') release(entry)
      }
    },
    drainOwners(ownerKeys: string[]) {
      const keys = new Set(ownerKeys.filter(Boolean))
      const ownerBusy = [...entries.values()].some((entry) => keys.has(entry.principal.ownerKey))
      if (!ownerBusy) return Promise.resolve()
      return new Promise<void>((resolve) => ownerDrainWaiters.add({ ownerKeys: keys, resolve }))
    },
    snapshot() {
      const values = [...entries.values()]
      return {
        accepting,
        active: values.filter((entry) => entry.committed && entry.slot === 'active').length,
        queued: values.filter((entry) => entry.committed && entry.slot === 'queued').length,
        reserved: values.filter((entry) => !entry.committed).length,
        tracked: tracked.size,
      }
    },
    drain() {
      if (!entries.size && !tracked.size) return Promise.resolve()
      return new Promise<void>((resolve) => drainWaiters.add(resolve))
    },
  }
}

